import { PLAYLIST_TRANSITION_HELP } from "../help-text.js";

const IFRAME_FIELDS_HELP = " An iframe primitive takes optional reload_s (0, the default, never reloads; 60 to 86400 loads src again every reload_s seconds while the page is on glass), optional fallback_src (the page shown when src does not load, with the forms and rules of src; a recovered src replaces it at the next reload) and optional navigation_allowlist (1 to 64 host-sources of the form [scheme://]host[:port][path], such as example.com, *.example.com or https://example.com/docs/; with a list, the page's links, scripted navigations and redirects reach only src, fallback_src and matching addresses; omit it for no restriction, an empty list is refused). The src and fallback_src of an iframe may carry screen tokens in the path, query or fragment of an http or https address: {screen.id} (the screen id without its scr_ prefix), {screen.name}, {screen.timezone}, {screen.field.NAME}, {screen.location.lat}, {screen.location.lon}, {screen.location.name} and {screen.location.address}. The playlist stores the address as written, braces kept, and each screen's manifest carries its own address with every value percent-encoded for its place in it; a screen that lacks a value gets no iframe, and the write answers with a screen_fact_missing warning that names the screens. A token in the scheme, credentials, host or port, or in a YouTube, document or BI view address, is invalid_request at src. An application primitive takes optional params (up to 16 names of lower case letters, digits and underscores, ticket and policy reserved, values up to 512 characters, the same tokens) that its launch URL carries as query parameters after ticket.";

const DOCUMENT_LINK_HELP = IFRAME_FIELDS_HELP + " An iframe page whose src or fallback_src is a Google Slides, Docs or Sheets share, Publish to web or embed link, or a Microsoft 365 Embed link (File → Share → Embed in Word, Excel or PowerPoint on OneDrive or SharePoint), is stored rebuilt for the screen: Slides and PowerPoint decks loop, a Slides deck advances on the link's own delay held to the page duration (give the page the time of the whole deck), and Docs, Sheets, Word and Excel reload every 5 minutes. A file that asks viewers to sign in is refused with document_not_shared, whose detail names the sharing setting to change.";

